const status=Number($json.statusCode); const campaign=$json.body?.data;
if(status!==200) throw new Error(`MailerLite report failed: HTTP ${status}; ${JSON.stringify($json.body?.errors||$json.body?.message||'unknown error')}`);
const s=campaign?.stats||campaign?.emails?.[0]?.stats;
if(!campaign?.id||!s) throw new Error('MailerLite report schema invalid: campaign id or email statistics missing');
return [{json:{campaign:{id:campaign.id,name:campaign.name,status:campaign.status,scheduled_for:campaign.scheduled_for,finished_at:campaign.finished_at},stats:{sent:Number(s.sent||0),unique_opens:Number(s.unique_opens_count||0),unique_clicks:Number(s.unique_clicks_count||0),unsubscribes:Number(s.unsubscribes_count||0),spam:Number(s.spam_count||0),hard_bounces:Number(s.hard_bounces_count||0),soft_bounces:Number(s.soft_bounces_count||0)},targets:{open_rate:Number($('Workflow Configuration').item.json.target_open_rate),ctr:Number($('Workflow Configuration').item.json.target_ctr)},refreshed_at:new Date().toISOString()}}];
